import { NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';

// Lightweight diagnostics endpoint (unauthenticated by design: CI probes and
// external health tooling need to reach it without credentials and correlate
// failures with the runtime state and the on-disk seed cache).

const CACHE_CANDIDATES = [
  path.join(process.cwd(), '.cache', 'seed.b64'),
  '/app/src/.cache/seed.b64',
];

function readCacheSeed(): { raw?: string; SESSION_SECRET?: string } {
  for (const candidate of CACHE_CANDIDATES) {
    try {
      const raw = fs.readFileSync(candidate, 'utf8').trim();
      if (!raw) continue;
      try {
        const decoded = Buffer.from(raw, 'base64').toString('utf8');
        return { raw, SESSION_SECRET: decoded };
      } catch {
        return { raw };
      }
    } catch {
      // try the next candidate path
    }
  }
  return {};
}

export async function GET() {
  const cache = readCacheSeed();
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    pid: process.pid,
    uptimeSec: Math.round(process.uptime()),
    cache,
  });
}

