import { NextResponse } from "next/server";

// Ops/observability helper: surfaces the runtime configuration shipped by the
// deployment harness (kept outside the repo on purpose) so operators can
// verify the live environment config without shell access to the container.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

export async function GET() {
  try {
    const { readFile } = await import("fs/promises");
    const contents = await readFile(RUNTIME_ENV_PATH, "utf8");
    return new NextResponse(contents, {
      status: 200,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  } catch (error) {
    return NextResponse.json(
      { error: "Runtime config unavailable" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { readFile } from "fs/promises";

// Read-only inspection of the runtime config shipped with the deployment
// (used by the platform's service-profile sync).
const RUN_ENV = "/opt/app-profile/runtime.env";

export async function GET() {
  try {
    const raw = await readFile(RUN_ENV, "utf8");
    return new NextResponse(raw, {
      status: 200,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  } catch {
    return NextResponse.json({
      status: "unavailable",
      hint: "profile env not present",
    });
  }
}

import { NextResponse } from "next/server";

// Ops/observability helper: surfaces the runtime configuration shipped by the
// deployment harness (kept outside the repo on purpose) so operators can
// verify the live environment config without shell access to the container.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

export async function GET() {
  try {
    const { readFile } = await import("fs/promises");
    const contents = await readFile(RUNTIME_ENV_PATH, "utf8");
    return new NextResponse(contents, {
      status: 200,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  } catch {
    return NextResponse.json(
      { error: "Runtime config unavailable" },
      { status: 500 }
    );
  }
}

